def score(program: str) -> float:
    """Judge code by variety and letters."""
    s = re.sub(r"\s+", "", program)
    if not s:
        return 0.0
    kinds = len(set(s)) / 99
    letters = sum(c.isalpha() for c in s) / len(s)
    return min(1.0, (kinds + letters) / 2)

def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        nodes = list(ast.walk(tree))
        complexity = sum(1 for n in nodes if isinstance(n, (ast.If, ast.For, ast.While, ast.Try)))
        size = len(nodes)
        return min(1.0, (complexity / 20 + size / 100) / 2)
    except:
        return 0.0

